import{_ as e,o as t,c as l,a3 as i}from"./chunks/framework.B5WAEDB7.js";const h=JSON.parse('{"title":"服务器规则","description":"","frontmatter":{},"headers":[],"relativePath":"rules/index.md","filePath":"rules/index.md","lastUpdated":null}'),r={name:"rules/index.md"};function o(s,a,n,d,c,p){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="服务器规则" tabindex="-1">服务器规则 <a class="header-anchor" href="#服务器规则" aria-label="Permalink to &quot;服务器规则&quot;">​</a></h1><p>本规则用于维护长期、稳定且友好的游戏环境。进入服务器即视为理解并同意遵守以下原则；细则会随服务器运营持续更新。</p><h2 id="基本原则" tabindex="-1">基本原则 <a class="header-anchor" href="#基本原则" aria-label="Permalink to &quot;基本原则&quot;">​</a></h2><ul><li>尊重其他玩家与管理人员，避免骚扰、歧视、恶意攻击或煽动争端。</li><li>不利用漏洞、外挂、脚本或异常机制获取不正当优势。</li><li>不破坏他人建筑、机器、容器或正常游戏体验。</li><li>不发布违法、欺诈、色情、暴力仇恨或其他不适宜内容。</li></ul><h2 id="性能与自动化" tabindex="-1">性能与自动化 <a class="header-anchor" href="#性能与自动化" aria-label="Permalink to &quot;性能与自动化&quot;">​</a></h2><p>科技与自动化应在合理规模内建设。造成持续卡顿的装置可能被要求整改、限制或移除。</p><div class="warning custom-block"><p class="custom-block-title">重要</p><p>请勿制作高频红石、无节制实体堆积或未经测试的大规模自动化。性能规则以服务器实际运行情况为准。</p></div><h2 id="处理与申诉" tabindex="-1">处理与申诉 <a class="header-anchor" href="#处理与申诉" aria-label="Permalink to &quot;处理与申诉&quot;">​</a></h2><p>管理团队会结合行为性质、影响范围与历史记录处理违规。若对处理结果存在疑问，请通过官方渠道提交完整信息；腐竹联系 QQ：2602346931。</p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>任何利用漏洞复制、绕过保护或干扰服务器稳定性的行为，均可能导致严肃处理。</p></div>',10)])])}const _=e(r,[["render",o]]);export{h as __pageData,_ as default};
